import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BQ1gajhD.js";const p=JSON.parse('{"title":"北京夜游指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nightlife.md","filePath":"guide/nightlife.md","lastUpdated":1787045959000}'),l={name:"guide/nightlife.md"};function o(n,a,h,d,s,u){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="北京夜游指南" tabindex="-1">北京夜游指南 <a class="header-anchor" href="#北京夜游指南" aria-label="Permalink to &quot;北京夜游指南&quot;">​</a></h1><blockquote><p>&quot;白天属于景点，夜晚属于灯火。&quot;</p></blockquote><h2 id="夜景第一梯队" tabindex="-1">夜景第一梯队 <a class="header-anchor" href="#夜景第一梯队" aria-label="Permalink to &quot;夜景第一梯队&quot;">​</a></h2><h3 id="国贸商城观景台-免费" tabindex="-1">国贸商城观景台（免费） <a class="header-anchor" href="#国贸商城观景台-免费" aria-label="Permalink to &quot;国贸商城观景台（免费）&quot;">​</a></h3><p>国贸商城北区6层露天观景台是看 CBD 夜景最划算的地方：<strong>免费、不用预约</strong>，地铁1/10号线国贸站E2口直达。正对央视「大裤衩」、中国尊和整条 CBD 天际线，日落前后半小时是黄金时段——先看晚霞，再看楼宇逐一亮灯。</p><h3 id="亮马河国际风情水岸" tabindex="-1">亮马河国际风情水岸 <a class="header-anchor" href="#亮马河国际风情水岸" aria-label="Permalink to &quot;亮马河国际风情水岸&quot;">​</a></h3><p>亮马河夜航是近几年最热门的城市夜景项目，沿河灯光秀分段呈现，两岸酒吧与使馆区的灯光倒映水面。不坐船也可以沿河步行，全程轻松，适合晚饭后消食。</p><h2 id="夜景第二梯队" tabindex="-1">夜景第二梯队 <a class="header-anchor" href="#夜景第二梯队" aria-label="Permalink to &quot;夜景第二梯队&quot;">​</a></h2><h3 id="鸟巢与水立方" tabindex="-1">鸟巢与水立方 <a class="header-anchor" href="#鸟巢与水立方" aria-label="Permalink to &quot;鸟巢与水立方&quot;">​</a></h3><p>奥体中心区域的夜景是「钢筋水泥中的温柔」：鸟巢红色灯带与水立方蓝色泡泡形成鲜明对比，奥林匹克森林公园内的中轴景观灯同样值得散步。地铁8号线奥体中心站可达，晚上比白天更有氛围。</p><h3 id="什刹海夜色" tabindex="-1">什刹海夜色 <a class="header-anchor" href="#什刹海夜色" aria-label="Permalink to &quot;什刹海夜色&quot;">​</a></h3><p>什刹海是北京最有市井气的夜景：银锭桥上看后海灯火，沿岸酒吧音乐与胡同晚风交织。从钟鼓楼方向走过来，还能顺路拍一组鼓楼夜景。</p><h3 id="三里屯太古里-蓝色港湾" tabindex="-1">三里屯太古里 / 蓝色港湾 <a class="header-anchor" href="#三里屯太古里-蓝色港湾" aria-label="Permalink to &quot;三里屯太古里 / 蓝色港湾&quot;">​</a></h3><ul><li><strong>三里屯太古里</strong>：潮流夜生活的代名词，灯光设计感强，适合喜欢都市感的人</li><li><strong>蓝色港湾</strong>：欧式小镇建筑配灯光喷泉，傍晚散步氛围最佳</li></ul><h2 id="夜游实用提示" tabindex="-1">夜游实用提示 <a class="header-anchor" href="#夜游实用提示" aria-label="Permalink to &quot;夜游实用提示&quot;">​</a></h2><ul><li>大部分公园型景点晚 20:00-22:00 闭园，夜景以开放式街区、观景台与商圈为主</li><li>亮马河夜航旺季需提前购票，建议傍晚再确认一次当日班次</li><li>秋冬夜游务必带外套，CBD 与河岸风大</li><li>夜间回程优先地铁：国贸（1/10号线）、亮马河（10号线亮马桥站）、鸟巢（8号线）夜间末班车都在 22:30 以后</li></ul>',16)])])}const q=e(l,[["render",o]]);export{p as __pageData,q as default};
